import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    names = input[1:]

    graph = defaultdict(list)
    indegree = {chr(i): 0 for i in range(ord('a'), ord('z') + 1)}

    def add_edge(u, v):
        graph[u].append(v)
        indegree[v] += 1

    for i in range(n - 1):
        for j in range(i + 1, n):
            name1, name2 = names[i], names[j]
            min_len = min(len(name1), len(name2))
            found = False
            for k in range(min_len):
                if name1[k] != name2[k]:
                    add_edge(name1[k], name2[k])
                    found = True
                    break
            if not found and len(name1) > len(name2):
                print("Impossible")
                return

    queue = deque([char for char in indegree if indegree[char] == 0])
    result = []

    while queue:
        char = queue.popleft()
        result.append(char)
        for neighbor in graph[char]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) == 26:
        print(''.join(result))
    else:
        print("Impossible")

main()
